import{_ as t,o as r,c as e,ag as n}from"./chunks/framework.KxDd3USm.js";const C=JSON.parse('{"title":"06.9 精华题与专项题","description":"","frontmatter":{},"headers":[],"relativePath":"06-计算机网络/91-精华题与专项题.md","filePath":"06-计算机网络/91-精华题与专项题.md"}'),s={name:"06-计算机网络/91-精华题与专项题.md"};function p(a,o,c,d,g,A){return r(),e("div",null,[...o[0]||(o[0]=[n('<h1 id="_06-9-精华题与专项题" tabindex="-1">06.9 精华题与专项题 <a class="header-anchor" href="#_06-9-精华题与专项题" aria-label="Permalink to &quot;06.9 精华题与专项题&quot;">​</a></h1><p><strong>1.</strong> 在 OSI 参考模型中，实现数据加密与压缩等格式转换功能的是（）。 A. 应用层 B. 会话层 C. 表示层 D. 传输层</p><p><strong>2.</strong> 某主机 IP 地址为 130.24.35.66/22，其所在子网的广播地址是（）。 A. 130.24.35.255 B. 130.24.32.255 C. 130.24.36.255 D. 130.24.63.255</p><p><strong>3.</strong> 将 202.113.76.0/24、202.113.77.0/24、202.113.78.0/24、202.113.79.0/24 聚合后得到的地址是（）。 A. 202.113.76.0/22 B. 202.113.77.0/22 C. 202.113.76.0/23 D. 202.113.76.0/21</p><p><strong>4.</strong> TCP 连接建立过程中，服务器在收到客户端的 ACK 报文后进入的状态是（）。 A. LISTEN B. SYN-RCVD C. SYN-SENT D. ESTABLISHED</p><p><strong>5.</strong> 下列协议中，属于 TCP/IP 网际层（网络层）的是（）。 A. UDP B. ICMP C. FTP D. SMTP</p><p><strong>6.</strong> 某单位分得 C 类网络 200.15.64.0/24，要求划分出至少 12 个子网，并使每个子网的可用主机数尽可能多，应选用的子网掩码是（）。 A. 255.255.255.192 B. 255.255.255.224 C. 255.255.255.240 D. 255.255.255.248</p><p><strong>7.</strong> 对网段 192.168.5.0/24 进行子网划分，要求每个子网最多接入 30 台主机，最多可划分出的子网数是（）。 A. 4 B. 8 C. 16 D. 32</p><hr><h2 id="扩充专项题-本轮新增" tabindex="-1">扩充专项题（本轮新增） <a class="header-anchor" href="#扩充专项题-本轮新增" aria-label="Permalink to &quot;扩充专项题（本轮新增）&quot;">​</a></h2><p><strong>1.</strong> 一台主机发送 HTTP 数据时，数据自上而下封装后的单位顺序正确的是（）。 A. 数据 → 帧 → 段 → 分组 → 比特 B. 数据 → 段 → 分组 → 帧 → 比特 C. 数据 → 分组 → 段 → 帧 → 比特 D. 数据 → 段 → 帧 → 分组 → 比特</p><p><strong>2.</strong> 数据链路层交给物理层的数据单位是（）。 A. 比特 B. 帧 C. 分组 D. TCP 段</p><p><strong>3.</strong> 主机 A 的地址为 192.168.10.20/24，默认网关为 192.168.10.1。A 向 10.1.1.8 发送数据时，第一跳以太网帧的目的 MAC 地址应当是（）。 A. A 自己的 MAC 地址 B. 10.1.1.8 的 MAC 地址 C. 默认网关 192.168.10.1 对应的 MAC 地址 D. 受限广播地址对应的 MAC 地址</p><p><strong>4.</strong> 关于 NAT 的说法，正确的是（）。 A. NAT 能把私网地址转换为公网侧地址，并可让多台内网主机共享公网 IPv4 地址 B. 使用 NAT 后就不再需要任何安全防护 C. NAT 要求每台内网主机必须拥有不同的公网地址 D. NAT 只改变数据链路层的 MAC 地址，不涉及 IP 或端口</p><p><strong>5.</strong> 某 TCP 连接的接收窗口 <code>rwnd = 24 KB</code>，拥塞窗口 <code>cwnd = 10 KB</code>。忽略已发送未确认数据后，当前发送窗口上限是（）。 A. 10 KB B. 14 KB C. 24 KB D. 34 KB</p><p><strong>6.</strong> 等长数据段编号为 1、2、3……，发送窗口原为 <code>[1,4]</code>。发送方已收到对 1、2 的累计确认，则窗口应滑动为（）。 A. <code>[2,5]</code> B. <code>[3,6]</code> C. <code>[4,7]</code> D. <code>[5,8]</code></p><p><strong>7.</strong> 对 URL <code>https://learn.example.org:8443/course?id=6</code>，其完整主机名是（）。 A. <code>https</code> B. <code>learn</code> C. <code>learn.example.org</code> D. <code>/course</code></p><p><strong>8.</strong> 某电脑可以直接访问已知公网 IP，也能正常使用已有的即时通信连接，但在浏览器中输入任何域名都无法打开网页。最可能的故障是（）。 A. DNS 配置或解析异常 B. 网卡物理损坏 C. 本地链路完全中断 D. CPU 故障</p><p><strong>9.</strong> 关于 HTTP GET 与 POST 的说法，正确的是（）。 A. GET 天然加密，POST 使用明文 B. POST 天然加密，GET 使用明文 C. GET 常用于获取资源，POST 常用于提交数据；是否加密取决于是否使用 HTTPS D. GET 只能传输文字，POST 才能得到网页</p><p><strong>10.</strong> 下列最符合“服务器端动态网页”的是（）。 A. 服务器对所有用户直接返回同一个已保存的 HTML 文件 B. 服务器根据登录用户和数据库中的订单记录生成页面内容 C. 交换机依据 MAC 地址转发数据帧 D. DNS 服务器把域名解析成 IP 地址</p><hr>',21)])])}const _=t(s,[["render",p]]);export{C as __pageData,_ as default};
